      "raw_content": "카페홈\n좌담회알바좌담회카페\n검색\n메뉴\n새로운 좌담/설문\n앱 열기\n10/6~7) 만 18세 ~ 54세 성인 여성)캡슐커피 이용자 AI 인터뷰\n본문 기타 기능\n좌담회알바좌담회카페\n카페매니저\n채팅\n작성일\n2026.09.30. 13:50\n조회 218\n구독\n10/6~7) 만 18세 ~ 54세 성인 남녀)캡슐커피 이용자 AI 인터뷰\n캡슐 커피 이용 경험에 대한 의견을 나누어 주실 참가자를 모집합니다.\n본 조사는 AI 가이드에 따라 진행되는 온라인 인터뷰로 웹캠과 마이크를 켜고 대화하는 방식으로 진행됩니다.\n1. 참가 자격\n연령/성별: 만 18세 ~ 54세 성인 남녀\n커피 음용 습관:\n매일 하루 2~3잔 이상 커피를 즐겨 드시는 분\n캡슐 커피 머신을 보유하고, 캡슐을 정기적으로 구매하여 이용하시는 분\n필수 제출 사항: 추후 현재 사용 중인 캡슐 커피 머신 실물 사진 제출 필수\n참여 환경: 웹캠과 마이크가 장착된 PC 또는 노트북 사용 가능자 (모바일 참여 불가)\n2. 조사 일정 및 방식\n조사 방식: AI 진행 비동기식 온라인 조사 (40분 내 소요)\n조사 일정: 아래 일정 중 가능한 시간대 선택 (기재된 시간보다 15분 전 참석해 테크체크 필수진행)\n10/6(화): 오전 11시 / 오후 2시 / 오후 4시 30분\n10/7(수): 오전 11시 / 오후 2시 / 오후 4시 30분\n참가 사례비: 35,000원\n3. 신청 방법\n아래 링크를 통해 머신 사진 첨부 및 참여 가능 시간대를 선택하여 신청서를 제출해 주시면 확인 후 개별 연락드립니다.\n소개자 이름에 소개자명 송난주 반드시!!!! 누락없이 작성 바랍니다.\nhttps://survey-insight.com/?ACCESS_KEY=d7fc1030-abc1-4a32-a631-af42044902b3&UID=\n소개자 이름에 소개자명 송난주 반드시!!!! 누락없이 작성 바랍니다.\n좋아요\n1\n좋아요한 사람 목록으로 이동\n송파구에서 핫한 진짜 동네 이야기\n댓글\n1\n클린봇 이 악성 댓글을 감지합니다.\n댓글 알림 설정\n큰돌찬\n신입회원\nNew\n감사합니다\n2026.09.30. 17:56 답글쓰기\n옵션\n좋아요\n댓글을 남겨보세요\n전체글\n25~45세(고졸이상) 내근직_리서치 업무 보조- 아르바이트\n좌담회알바좌담회카페\n26.09.30.\n댓글\n1\n10/6~7) 만 18세 ~ 54세 성인 여성)캡슐커피 이용자 AI 인터뷰\n좌담회알바좌담회카페\n26.09.30.\n댓글\n1\n10/6~7) 만 18세 ~ 54세 성인 남성)캡슐커피 이용자 AI 인터뷰\n좌담회알바좌담회카페\n26.09.30.\n댓글\n1\n급급급) 만 18–35세 성인 여성 ) AI 평가단 100명 모집\n좌담회알바좌담회카페\n26.09.30.\n댓글\n3\n5페이지중 1페이지 버튼\n5페이지중 2페이지 버튼\n5페이지중 3페이지 버튼\n5페이지중 4페이지 버튼\n5페이지중 5페이지 버튼\n새로운 좌담/설문\n 게시판\n의 글을 많이 보셨네요. 👀\n구독하고 관심글을 빠르게 확인하세요!\n게시판 구독하기\n목록으로\n좋아요\n1\n좋아요한 사람 목록으로 이동\n댓글\n1\n새로운 댓글\n공유하기\n새 글, 새 댓글을 놓치지 않게 카페앱으로 이용해보세요!\n앱으로 보기\n앱 설치하기\n네이버 메인에 추가\n맨위로\n로그아웃전체서비스PC버전\n이용약관\n개인정보처리방침\n카페 고객센터\n카페 공지사항\n오류신고\n© NAVER Corp.대표번호 : 1588-3820",
