      "type": "좌담회",
      "raw_content": "카페홈\n좌담회알바좌담회카페\n검색\n메뉴\n새로운 좌담/설문\n앱 열기\n10/13) 30-54세 남녀) DC/IRP 보유자 대상 좌담회\n본문 기타 기능\n좌담회알바좌담회카페\n카페매니저\n채팅\n작성일\n2026.09.30. 14:13\n조회 110\n구독\n10/13) 30-54세 남녀) DC/IRP 보유자 대상 좌담회\n- 대상 : 서울/수도권 거주하는 30-54세 남녀\n- 장소 : 방배역 근처(자세한 장소는 확정 후 안내)\n- 일정 : 2026년 10월 13일 중 한타임(2시간 30분 진행)\n- 사례비 : 5만원\n* 신청방법\n이름/연락처/생년월일/직업/거주지 작성 후 아래 질문에 응답해주세요\n질문1) DC 또는 IRP 중 현재 보유하고 계신 상품을 작성해주세요\n질문2) 현재 보유하고 있는 DC/IRP를 가입하신 지 대략 얼마나 되셨나요? **둘다 보유라면 각각 가입 기간을 작성해주세요\n질문3) DC/IRP 계좌 내 투자상품(펀드, ETF 등) 정보를 얼마나 자주 검색하시나요?(골고루 모집 예정이니 솔직한 응답 부탁드립니다) EX) 주기적으로, 가끔, 거의 안봄\n질문4) 최근 6개월 이내 DC/IRP 퇴직연금상품으로 실제 경험 해본 것을 모두 선택해주세요 **보기) 잔고조회, 상품탐색, 매수/매두(상품 포트폴리오 재구성)\n질문5) DC/IRP 계좌 내 투자상품 포트폴리오 점검 또는 리밸런싱을 얼마나 자주 하시나요?(골고루 모집 예정이니 솔직한 응답 부탁드립니다) Ex) 월 1회, 6개월에 1회, 1년에 1회 등\n질문6) DC/IRP 연금상품으로 주로 선호하시는 상품 유형을 선택해주세요(골고루 모집 예정이니 솔직한 응답 부탁드립니다) **보기) 원리금보장형, 실적배당형\n질문7) 평소 금융상품에 대한 이해도를 선택해주세요(골고루 모집 예정이니 솔직한 응답 부탁드립니다) **보기) 매우낮음, 낮음, 평균, 높음, 매우높음\n질문8) DC/IRP 운영능력을 스스로 어떻게 평가하시나요?(골고루 모집 예정이니 솔직한 응답 부탁드립니다) **보기) 매우어려움, 어려움, 보통, 쉬움, 매우쉬움\n질문9) [현재 주식 투자자만] 현재 국내/해외 주식을 하고 계신 어플을 작성해주세요 **주식을 하지 않으시는 분들은 이용안함 작성\nhttps://forms.gle/T6qUtQUMcmLnBPPR7\n좋아요\n0\n송파구의 더 많은 인기글 보러가기\n댓글\n1\n클린봇 이 악성 댓글을 감지합니다.\n댓글 알림 설정\n큰돌찬\n신입회원\nNew\n감사합니다\n2026.09.30. 17:54 답글쓰기\n옵션\n좋아요\n댓글을 남겨보세요\n전체글\n고유링크) 10월~) 총 40만원 ) 20대이상 남성) 취미생활 관련 가정방문 조사\n좌담회알바좌담회카페\n26.09.30.\n댓글\n1\n10/13) 30-54세 남녀) DC/IRP 보유자 대상 좌담회\n좌담회알바좌담회카페\n26.09.30.\n댓글\n1\n10/8) 30-59세 남녀) 현재 KB라이프 보험 보유자 대상 좌담회\n좌담회알바좌담회카페\n26.09.30.\n댓글\n1\n25~45세(고졸이상) 내근직_리서치 업무 보조- 아르바이트\n좌담회알바좌담회카페\n26.09.30.\n댓글\n1\n5페이지중 1페이지 버튼\n5페이지중 2페이지 버튼\n5페이지중 3페이지 버튼\n5페이지중 4페이지 버튼\n5페이지중 5페이지 버튼\n새로운 좌담/설문\n 게시판\n의 글을 많이 보셨네요. 👀\n구독하고 관심글을 빠르게 확인하세요!\n게시판 구독하기\n목록으로\n좋아요\n0\n댓글\n1\n새로운 댓글\n공유하기\n새 글, 새 댓글을 놓치지 않게 카페앱으로 이용해보세요!\n앱으로 보기\n앱 설치하기\n네이버 메인에 추가\n맨위로\n로그아웃전체서비스PC버전\n이용약관\n개인정보처리방침\n카페 고객센터\n카페 공지사항\n오류신고\n© NAVER Corp.대표번호 : 1588-3820",
