      "raw_content": "카페홈\n좌담회알바좌담회카페\n검색\n메뉴\n수정&재공지 좌담/설문\n앱 열기\n고유링크) 10월~) 총 40만원 ) 20대이상 남성) 취미생활 관련 가정방문 조사\n본문 기타 기능\n좌담회알바좌담회카페\n카페매니저\n채팅\n작성일\n2026.09.30. 14:15\n조회 74\n구독\n고유링크) 10월~) 총 40만원 ) 20대이상 남성) 취미생활 관련 가정방문 조사\n신청하신분은 재신청 안하셔도 됩니다\n본 리서치는 성인 소비자들의 일상 속 취미 활동과 창의력, 상상력 기반의 브랜드 및 제품 경험을 알아보기 위한 리서치입니다.\n1. 리서치 개요\n평소 조립식 블록 및 건축 조립 세트를 즐기시거나, 다양한 창의적 취미(게임, 수공예, 스마트 홈데코, 프로그래밍/로보틱스 등)를 열정적으로 즐기는 성인 소비자분들의 라이프스타일과 관련된 깊이있는 의견을 듣고자 합니다.\n2. 참여 일정 및 절차\n사전 브리핑 콜: 10/5(월) ~ 10/14(수) 중 1회 (온라인 Zoom, 25분)\n사전과제: 10/16(금) ~10/18(일) (온라인, 30분 소요)\n자택 방문 인터뷰: 10/23(금) ~10/26(월) 중 1회 (3시간)\n3. 사례비: 총 40만원\n사전 브리핑 콜 & 사전과제 10 만원 / 자택 방문 인터뷰 30만원\n모든 단계 완료 후 이틀 안에 계좌 입금\n<좌담회알바 좌담회카페 단독 링크>\nhttps://forms.gle/EZyCQ53Xvf5BHhTq7\n좋아요\n0\n송파구에서 핫한 진짜 동네 이야기\n댓글\n1\n클린봇 이 악성 댓글을 감지합니다.\n댓글 알림 설정\n큰돌찬\n신입회원\nNew\n감사합니다\n2026.09.30. 17:54 답글쓰기\n옵션\n좋아요\n댓글을 남겨보세요\n전체글\n고유링크) 10월~) 총 40만원 ) 20대이상 여성) 취미생활 관련 가정방문 조사\n좌담회알바좌담회카페\n26.09.30.\n댓글\n1\n고유링크) 10월~) 총 40만원 ) 20대이상 남성) 취미생활 관련 가정방문 조사\n좌담회알바좌담회카페\n26.09.30.\n댓글\n1\n10/13) 30-54세 남녀) DC/IRP 보유자 대상 좌담회\n좌담회알바좌담회카페\n26.09.30.\n댓글\n1\n10/8) 30-59세 남녀) 현재 KB라이프 보험 보유자 대상 좌담회\n좌담회알바좌담회카페\n26.09.30.\n댓글\n1\n5페이지중 1페이지 버튼\n5페이지중 2페이지 버튼\n5페이지중 3페이지 버튼\n5페이지중 4페이지 버튼\n5페이지중 5페이지 버튼\n수정&재공지 좌담/설문\n 게시판\n의 글을 많이 보셨네요. 👀\n구독하고 관심글을 빠르게 확인하세요!\n게시판 구독하기\n목록으로\n좋아요\n0\n댓글\n1\n새로운 댓글\n공유하기\n새 글, 새 댓글을 놓치지 않게 카페앱으로 이용해보세요!\n앱으로 보기\n앱 설치하기\n네이버 메인에 추가\n맨위로\n로그아웃전체서비스PC버전\n이용약관\n개인정보처리방침\n카페 고객센터\n카페 공지사항\n오류신고\n© NAVER Corp.대표번호 : 1588-3820",
