      "raw_content": "카페홈\n좌담회알바좌담회카페\n검색\n메뉴\n새로운 좌담/설문\n앱 열기\n고유링크) 만 13~19세 남녀) AI 음성기능 관련 온라인 다이어리  및 1:1 인터뷰\n본문 기타 기능\n좌담회알바좌담회카페\n카페매니저\n채팅\n작성일\n2026.09.30. 20:23\n조회 18\n구독\n고유링크) 만 13~19세 남녀) AI 음성기능 관련 온라인 다이어리 및 1:1 인터뷰\n고유링크) 만 13~64세 남녀) AI 음성기능 관련 온라인 다이어리 및 1:1 인터뷰\n모집이 마감되면 링크가 열리지 않으니 참고 부탁드립니다 ~\n온라인 사전 OT(Zoom)이후, 5일 간 매일 20분씩 AI 음성기능 관련 경험에 대해 다이어리를 작성하는 조사입니다.\n다이어리 조사 종료 후, 일부 선정하여 1:1 인터뷰(1시간30분)를 진행할 예정입니다.\n1.? 대상 공통 조건: 최근 3개월 내 AI 툴 사용 경험이 있으며, 스마트폰을 사용하는 전국 거주 만 13~64세 남녀\n2. 진행방식:\n사전 OT: 10/16(금) 또는 10/19(월) 중 온라인(zoom)으로 30분 진행\n다이어리 작성: 10/19(월)~23(금) 5일 간 매일 20분씩 온라인으로 작성\n온라인 인터뷰: 11/2(월)~11/16(월) 중 개별 진행\n3. 사례비: 다이어리 7만원 (11/16 조사 종료 후 전체 일괄 지급 예정) / 다이어리 이후 1:1 인터뷰 진행 시, 5만원 추가하여 총 12만원 지급\n★ 신청해 주신 내용을 토대로 순차적으로 전화드릴 예정입니다. 저희 직원과의 전화통화 및 최종 선정절차를 거쳐 참여자로 등록되신 분에 한해 조사 참여가 가능합니다.\n조사장소 강남구 논현동 한국리서치 본사 (9호선:언주역)\n조사기간 2026-10-16 ~ 2026-11-16\n소요시간 3시간\n사례비 70,000원\n조사방법 모바일 다이어리 및 1:1 온라인 인터뷰(zoom)\n안내사항 신청해 주신 내용을 토대로 순차적으로 전화드릴 예정입니다. 저희 직원과의 전화통화 및 최종 선정절차를 거쳐 참여자로 등록되신 분에 한해 조사 참여가 가능합니다.\n조사 참여 고유링크\nhttps://www.hrc-ms.com/participate/improSurvey/798?refuser=23341&intro=2\n좋아요\n1\n좋아요한 사람 목록으로 이동\n송파구 이웃끼리 공유하는 동네 꿀정보\n댓글\n0\n클린봇 이 악성 댓글을 감지합니다.\n댓글 알림 설정\n첫 댓글을 남겨보세요\n전체글\n고유링크) 만 20~29세 남녀) AI 음성기능 관련 온라인 다이어리 및 1:1 인터뷰\n좌담회알바좌담회카페\n26.09.30.\n댓글\n0\n고유링크) 만 13~19세 남녀) AI 음성기능 관련 온라인 다이어리  및 1:1 인터뷰\n좌담회알바좌담회카페\n26.09.30.\n댓글\n0\n10/23~28) 만 20-49세 여성) 주류 맛 테스트 조사\n좌담회알바좌담회카페\n26.09.30.\n댓글\n0\n10/23~28) 만 20-49세 남성) 주류 맛 테스트 조사\n좌담회알바좌담회카페\n26.09.30.\n댓글\n0\n5페이지중 1페이지 버튼\n5페이지중 2페이지 버튼\n5페이지중 3페이지 버튼\n5페이지중 4페이지 버튼\n5페이지중 5페이지 버튼\n새로운 좌담/설문\n 게시판\n의 글을 많이 보셨네요. 👀\n구독하고 관심글을 빠르게 확인하세요!\n게시판 구독하기\n목록으로\n좋아요\n1\n좋아요한 사람 목록으로 이동\n댓글\n0\n공유하기\n새 글, 새 댓글을 놓치지 않게 카페앱으로 이용해보세요!\n앱으로 보기\n앱 설치하기\n네이버 메인에 추가\n맨위로\n로그아웃전체서비스PC버전\n이용약관\n개인정보처리방침\n카페 고객센터\n카페 공지사항\n오류신고\n© NAVER Corp.대표번호 : 1588-3820",
