      "raw_content": "카페홈\n좌담회알바좌담회카페\n검색\n메뉴\n새로운 좌담/설문\n앱 열기\n고유링크)10/15~17)초코 시리얼 맛테스트-만 25~39세 직장인 여성\n본문 기타 기능\n좌담회알바좌담회카페\n카페매니저\n채팅\n작성일\n2026.09.30. 20:36\n조회 85\n구독\n고유링크)10/15~17)초코 시리얼 맛테스트-만 25~39세 직장인 여성\n▶조사 대상:\n1. 최근 3개월 이내 초코 시리얼을 직접 구매하여 취식 경험이 있는 만 30~49세 유자녀 기혼 전업주부(또는 프리랜서) 여성 (초등학생 자녀와 함께 참여해야 가능)\n2. 최근 3개월 이내 초코 시리얼 취식 경험이 있는 초등학생 고학년(4~6학년) 및 중고등학생 남녀\n3. 최근 3개월 이내 초코 시리얼을 직접 구매하여 취식 경험이 있는 만 25~39세 직장인 여성\n▶일정: 10월 15일(목)~10월 17일(토) 중 다양한 시간대 선택가능 (택1)\n▶소요시간: 80분 내외 / 사례비: 30,000원\n★신청해 주신 내용을 토대로 순차적으로 전화 드릴 예정입니다. 저희 직원과 통화 후 참여자 명단에 등록이 되셔야 참여 가능합니다.\n★본 설문조사에는 시식 과정이 포함되어 있습니다.\n★전업주부이신 어머니께서 초4~초6 자녀와 함께 참여해주시는 조사입니다. 사례비는 한 분 당 3만원 입니다. (예: 어머니+자녀 2명 = 사례비 9만원)\n(자녀는 시리얼 맛테스트 단독 참여 가능, 전업 주부는 단독 참여 불가)\n★전업주부이신 어머니께서 초4~초6 자녀와 함께 참여해주시는 조사입니다. 사례비는 한 분당 3만원입니다. (예: 어머니+자녀 2명 = 사례비 9만원)\n(자녀는 시리얼 맛테스트 단독 참여 가능, 전업주부는 단독 참여 불가)\n조사장소 강남구 논현동 한국리서치 본사 (9호선:언주역)\n조사기간 2026-10-15 ~ 2026-10-19일 중 하루 / 시간은 추후 안내드립니다\n소요시간 1시간20분\n사례비 30,000원\n조사방법 80분 시리얼 맛테스트\n안내사항 이 조사는 시리얼을 직접 시식하는 과정이 포함되어 있습니다. 밀, 호두, 우유, 돼지고기, 메밀, 땅콩, 토마토, 복숭아, 달걀, 잣, 닭고기, 쇠고기에 대한 알레르기 반응이 있으시면 참여가 어렵습니다\n조사 참여 고유링크\nhttps://www.hrc-ms.com/participate/improSurvey/797?refuser=23341&intro=2\n좋아요\n1\n좋아요한 사람 목록으로 이동\n송파구에서 많이 본 동네소식 보러가기\n댓글\n0\n클린봇 이 악성 댓글을 감지합니다.\n댓글 알림 설정\n첫 댓글을 남겨보세요\n전체글\n고유링크) 2시간 7만) 10/8) 서울거주 만 26~34세 미혼여성 직장인) 음료 관련 좌담회\n좌담회알바좌담회카페\n26.09.30.\n댓글\n1\n고유링크)10/15~17)초코 시리얼 맛테스트-만 25~39세 직장인 여성\n좌담회알바좌담회카페\n26.09.30.\n댓글\n0\n고유링크)10/15~17)초코 시리얼 맛테스트-초등학생 고학년(4~6학년) 및 중고등학생 남녀\n좌담회알바좌담회카페\n26.09.30.\n댓글\n0\n고유링크)10/15~17) 초코 시리얼 맛테스트-만30~49세 유자녀 기혼 전업주부(또는 프리랜서) 여성 (초등학생 자녀동반)\n좌담회알바좌담회카페\n26.09.30.\n댓글\n0\n5페이지중 1페이지 버튼\n5페이지중 2페이지 버튼\n5페이지중 3페이지 버튼\n5페이지중 4페이지 버튼\n5페이지중 5페이지 버튼\n좌담회알바좌담회카페\n 님\n의 글을 3개 보셨네요. 👀\n구독하고 새로운 글을 놓치지 마세요!\n멤버 구독하기\n목록으로\n좋아요\n1\n좋아요한 사람 목록으로 이동\n댓글\n0\n공유하기\n새 글, 새 댓글을 놓치지 않게 카페앱으로 이용해보세요!\n앱으로 보기\n앱 설치하기\n네이버 메인에 추가\n맨위로\n로그아웃전체서비스PC버전\n이용약관\n개인정보처리방침\n카페 고객센터\n카페 공지사항\n오류신고\n© NAVER Corp.대표번호 : 1588-3820",
