      "raw_content": "카페홈\n좌담회알바좌담회카페\n검색\n메뉴\n새로운 좌담/설문\n앱 열기\n고유링크) 2시간 7만) 10/8) 서울거주 만 26~34세 기혼여성 직장인) 음료 관련 좌담회\n본문 기타 기능\n좌담회알바좌담회카페\n카페매니저\n채팅\n작성일\n2026.09.30. 20:47\n조회 17\n구독\n고유링크) 2시간 7만) 10/8) 서울거주 만 26~34세 기혼여성 직장인) 음료 관련 좌담회\n고유링크) 2시간 7만) 10/8) 서울 경기 거주 만 26~34세 여성 직장인) 음료 관련 좌담회\n내용은 다음과 같고, 이번에도 구글 설문 통해서 신청 받으며, 1그룹(8명) 진행합니다.\n<내용>\n음료 관련 좌담회 참석자 모집\n저희 회사에서는 <음료 개발>을 위해 소비자 좌담회를 준비하고 있습니다.\n본 설문은 좌담회에 적합한 참석자를 모시기 위한 사전 질문이며, 응답 내용은 통계법에 의해 보호됩니다.\n아래 조건에 맞는 분들의 신청 부탁드립니다.\n[좌담회 신청]\n◯ 모집 대상 : 아래 조건을 모두 만족시키는 분\n1) 서울 경기 거주 만 26~34세 여성\n2) 매일 직장 출퇴근자 : 주로 실내 사무실에서 일하시는 분\n3) 음료를 자주 구매하여 드시는 분(생수 제외)\n◯ 사례비 : 7만원\n◯ 날짜 : 10월 8일(목) 오후 3시 ~ 5시\n◯ 장소 : 2호선 선릉역\n◯ 신청 : 아래 고유링크에서 이름, 연락처, 사전질문 작성\nhttps://forms.gle/8iyNmTwUjNH8LuRN7\n전화를 통해 사전선정질문을 하여 적합한 분만 참석 가능하기 때문에 혹시 조건이 맞지 않는 경우 참석할 수 없음을 미리 알려드립니다.\n감사합니다.\n좋아요\n2\n좋아요한 사람 목록으로 이동\n'좋아요'로 마음을 나누세요!\n송파구 이웃끼리 공유하는 동네 꿀정보\n댓글\n1\n클린봇 이 악성 댓글을 감지합니다.\n댓글 알림 설정\n토끼와 거북\n신입회원\nNew\n2026.10.01. 00:03 답글쓰기\n옵션\n좋아요\n3\n댓글을 남겨보세요\n전체글\n고유링크) 2시간 7만) 10/8) 경기도 거주 만 26~34세 미혼여성 직장인) 음료 관련 좌담회\n좌담회알바좌담회카페\n26.09.30.\n댓글\n1\n고유링크) 2시간 7만) 10/8) 경기도 거주 만 26~34세 기혼여성 직장인) 음료 관련 좌담회\n좌담회알바좌담회카페\n26.09.30.\n댓글\n1\n고유링크) 2시간 7만) 10/8) 서울거주 만 26~34세 기혼여성 직장인) 음료 관련 좌담회\n좌담회알바좌담회카페\n26.09.30.\n댓글\n1\n고유링크) 2시간 7만) 10/8) 서울거주 만 26~34세 미혼여성 직장인) 음료 관련 좌담회\n좌담회알바좌담회카페\n26.09.30.\n댓글\n1\n5페이지중 1페이지 버튼\n5페이지중 2페이지 버튼\n5페이지중 3페이지 버튼\n5페이지중 4페이지 버튼\n5페이지중 5페이지 버튼\n좌담회알바좌담회카페\n 님\n의 글을 3개 보셨네요. 👀\n구독하고 새로운 글을 놓치지 마세요!\n멤버 구독하기\n목록으로\n좋아요\n2\n좋아요한 사람 목록으로 이동\n댓글\n1\n새로운 댓글\n공유하기\n새 글, 새 댓글을 놓치지 않게 카페앱으로 이용해보세요!\n앱으로 보기\n앱 설치하기\n네이버 메인에 추가\n맨위로\n로그아웃전체서비스PC버전\n이용약관\n개인정보처리방침\n카페 고객센터\n카페 공지사항\n오류신고\n© NAVER Corp.대표번호 : 1588-3820",
