      "raw_content": "# # AI 음성기능 관련 모바일 다이어리 및 1:1 온라인 인터뷰\n*대상조건: 최근 3개월 내 AI 툴 사용 경험이 있으며, 스마트폰을 사용하는 전국 거주 만 13~64세 남녀\n*조사방식: 모바일 다이어리 및 1:1 온라인 화상 인터뷰(Zoom)\n*일정:\n-사전 OT: 10월 16일(금) 또는 10월 19일(월) 중 온라인(Zoom) 30분\n-다이어리 작성: 10월 19일(월) ~ 10월 23일(금) (5일간 매일 20분 온라인 작성)\n-온라인 인터뷰: 11월 2일(월) ~ 11월 16일(월) 중 개별 진행 (다이어리 종료 후 일부 선정자 대상)\n*소요시간: 사전 OT 30분 + 5일간 매일 20분 (1:1 인터뷰 대상자 1시간 30분 추가)\n*사례비: 다이어리 70,000원 (1:1 인터뷰 진행 시 50,000원 추가되어 총 120,000원 지급)\n*장소: 온라인 (Zoom 및 모바일 다이어리)\n<신청 방법>아래 신청버튼을 클릭하여 설문응답 진행해주세요. 신청해 주신 내용을 바탕으로 대상자가 되시면 저희가 순차적으로 전화 드립니다. 통화 후 참여 명단에 등록해드리며, 명단에 등록되셔야 참여 가능하니 참고 부탁드립니다.\n참가를 원하시는 분은 아래 버튼을 눌러 신청해 주세요.\n좌담회 신청하기 ➜\n글 탐색\n초코 시리얼 맛테스트 참여자 모집",
